'use strict';

const $ = (s, root = document) => root.querySelector(s);
const esc = (value) => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num = v => Number.isFinite(Number(v)) && v !== null && v !== '' ? Number(v).toLocaleString() : '—';
const short = v => v ? String(v).slice(0, 10) : 'Unknown';
const date = v => { const d = new Date(v); return v && !Number.isNaN(d.getTime()) ? d.toLocaleDateString(undefined, {month:'short', day:'numeric', year:'numeric'}) : 'Not recorded'; };
const time = v => { const d = new Date(v); return v && !Number.isNaN(d.getTime()) ? d.toLocaleString(undefined, {month:'short',day:'numeric',hour:'numeric',minute:'2-digit'}) : 'Never'; };
const url = v => { try { const u = new URL(v); return ['http:', 'https:'].includes(u.protocol) ? u.href : '#'; } catch { return '#'; } };
const labels = {current:'Up to date',updates:'Update available',unknown:'Not checked',error:'Check failed',diverged:'Diverged',active:'Active',archived:'Archived',candidate:'Candidate',passed:'Passed',pass:'Passed',failed:'Failed',fail:'Failed',partial:'Partial',incomplete:'Incomplete',running:'Running',queued:'Queued',done:'Complete',completed:'Complete',success:'Complete',new:'New',dismissed:'Dismissed',added:'Added',unobserved:'Unobserved',uncloned:'No source revision','local-ahead':'Local ahead',interrupted:'Interrupted',private:'Private', 'no-remote':'No remote',gone:'Gone'};
const badge = (status, text) => `<span class="pill dot ${esc(String(status || 'unknown').replace(/[^a-z-]/g,''))}">${esc(text || labels[status] || status || 'Unknown')}</span>`;
const runLabel = status => ({unknown:'Outcome unknown',error:'Execution error',timeout:'Timed out',partial:'Partial run'}[status] || labels[status] || status || 'Outcome unknown');
const runBadge = status => badge(status,runLabel(status));
const empty = (title, description, action = '') => `<div class="empty"><div class="empty-symbol" aria-hidden="true"><svg class="nav-icon" viewBox="0 0 24 24"><rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/></svg></div><h3>${esc(title)}</h3><p>${esc(description)}</p>${action}</div>`;
const field = (label, name, value = '', options = {}) => `<div class="form-field"><label for="field-${esc(name)}">${esc(label)}</label>${options.textarea ? `<textarea id="field-${esc(name)}" name="${esc(name)}" ${options.required?'required':''}>${esc(value)}</textarea>` : `<input id="field-${esc(name)}" name="${esc(name)}" type="${esc(options.type || 'text')}" value="${esc(value)}" ${options.required?'required':''} ${options.placeholder?`placeholder="${esc(options.placeholder)}"`:''} ${options.type==='number'?'min="0" step="1"':''}>`}${options.help?`<small>${esc(options.help)}</small>`:''}</div>`;
const selectField = (label, name, options, selected = '') => `<div class="form-field"><label for="field-${esc(name)}">${esc(label)}</label><select id="field-${esc(name)}" name="${esc(name)}">${options.map(([v,t])=>`<option value="${esc(v)}" ${String(selected)===String(v)?'selected':''}>${esc(t)}</option>`).join('')}</select></div>`;
const state = {repositories:[],hosts:[],queries:[],candidates:[],runs:[],jobs:[],settings:{},csrf_token:''};
const pageSize=60;
const view = {repoPage:0,historyPage:0,candidatePage:0,tab:'overview',search:'',repoStatus:'active',host:'',upstream:'',historySearch:'',historyStatus:'',historyRepo:'',candidateSearch:'',candidateStatus:'new',projectFilter:'confirmed',historyPhase:'test',groupSearch:'',groupUpstream:'',groupResult:'',gateA:'',gateB:'',query:'',detail:null};
let historyData={runs:[],total:0,loading:false,error:''},historyRequest=0,historyTimer;
const projectAttempted=new Set();let projectJob=null,projectStopped=false,projectObserver=null;
const selectedRepos=new Set();
let pollTimer, toastTimer, lastJobState = new Map(), isLoading = false;

function notify(message, error = false) { const toast = $('#toast'); toast.textContent = message; toast.classList.toggle('error', error); toast.hidden = false; clearTimeout(toastTimer); toastTimer = setTimeout(()=>toast.hidden=true,error?9000:4500); }
function runningJobs() { return state.jobs.filter(j=>['queued','running','pending'].includes(j.status)); }
async function api(path, data) {
  const response = await fetch(path, data === undefined ? {cache:'no-store'} : {method:'POST',headers:{'Content-Type':'application/json','X-Corpus-Token':state.csrf_token},body:JSON.stringify(data)});
  let result; try { result = await response.json(); } catch { throw new Error(`Server returned ${response.status}.`); }
  if (!response.ok) throw new Error(result.error || result.message || `Request failed (${response.status}).`);
  return result;
}
async function load({initial = false} = {}) {
  if (isLoading) return; isLoading=true;
  try {
    const next = await api('/api/state'); Object.assign(state, next);
    for (const k of ['repositories','hosts','queries','candidates','runs','jobs','events']) if (!Array.isArray(state[k])) state[k]=[];
    for (const j of state.jobs) { if (lastJobState.has(j.id) && ['queued','running','pending'].includes(lastJobState.get(j.id)) && !['queued','running','pending'].includes(j.status)) notify(j.message || `${j.kind || 'Job'} ${j.status}`,j.status==='error'||j.status==='failed'); }
    lastJobState=new Map(state.jobs.map(j=>[j.id,j.status]));if(projectJob){const j=state.jobs.find(x=>x.id===projectJob);if(j&&!['queued','running'].includes(j.status)){if(j.status==='failed')projectStopped=true;projectJob=null;}}
    render(); if(view.tab==='history')await loadHistory(); if (view.detail && $('#detail').open) renderDetail(view.detail); if ($('#modal').open && $('#modal').dataset.view==='activity') $('#modal .modal-body').innerHTML=activityBody();
  } catch(error) { if(initial) $('#main').innerHTML=empty('Could not connect',error.message,'<button data-action="reload" class="primary">Try again</button>'); else notify(error.message,true); }
  finally { isLoading=false;clearTimeout(pollTimer);pollTimer=setTimeout(()=>load(),runningJobs().length?3000:30000); }
}
async function loadHistory(){const seq=++historyRequest;historyData.loading=true;const query=new URLSearchParams({q:view.historySearch,offset:String(view.historyPage*pageSize),limit:String(pageSize)});if(view.historyPhase)query.set('phase',view.historyPhase);if(view.historyRepo)query.set('repo_id',view.historyRepo);if(view.historyStatus)query.set('status',view.historyStatus);try{const result=await api('/api/history?'+query);if(seq!==historyRequest)return;historyData={...result,loading:false,error:''};}catch(error){if(seq!==historyRequest)return;historyData={runs:[],total:0,loading:false,error:error.message};}if(view.tab==='history')render();}
function scheduleHistory(){clearTimeout(historyTimer);historyTimer=setTimeout(()=>loadHistory(),250);}
async function mutate(path,data,message){const result=await api(path,data);notify(result.job?'Job queued. You can keep working.':message||'Saved.');await load();return result;}
function pager(kind,count){const key=kind+'Page',page=view[key]||0,pages=Math.max(1,Math.ceil(count/pageSize));return `<span class="pagination"><button class="small quiet" data-action="page" data-kind="${kind}" data-offset="-1" ${page===0?'disabled':''}>← Previous</button><span>Page ${Math.min(page+1,pages)} of ${pages}</span><button class="small quiet" data-action="page" data-kind="${kind}" data-offset="1" ${page+1>=pages?'disabled':''}>Next →</button></span>`;}
function pageRows(rows,kind){const key=kind+'Page';view[key]=Math.max(0,Math.min(view[key]||0,Math.ceil(rows.length/pageSize)-1));return rows.slice(view[key]*pageSize,(view[key]+1)*pageSize);}
function activeRepos(){return state.repositories.filter(r=>r.status==='active');}
function hostName(id){return state.hosts.find(h=>h.id===id)?.label || id || 'Unknown host';}
function latestRun(repo){return [...(repo.runs||state.runs.filter(r=>r.repo_id===repo.id))].filter(r=>r.phase==='test'||!r.phase).sort((a,b)=>String(b.started_at||'').localeCompare(String(a.started_at||'')))[0];}
function render(){
  $('#repo-count').textContent=activeRepos().length; $('#candidate-count').textContent=state.candidates.filter(c=>c.status==='new').length;
  $('#activity-count').textContent=runningJobs().length?`(${runningJobs().length} active)`:'';
  document.querySelectorAll('[data-nav]').forEach(el=>{const active=el.dataset.nav===view.tab;el.classList.toggle('active',active);if(active)el.setAttribute('aria-current','page');else el.removeAttribute('aria-current');});
  const focused=document.activeElement?.id;const cursor=document.activeElement?.selectionStart;
  const groupScroll=new Map(Array.from(document.querySelectorAll('.group-column')).map(column=>[column.getAttribute('aria-labelledby'),column.querySelector('.group-cards')?.scrollTop||0]));
  const groupScrollLeft=$('.group-board')?.scrollLeft||0;
  const settingsForm=$('#main form[data-form="settings"]');
  const settingsDraft=settingsForm?.dataset.dirty==='true'?[...settingsForm.elements].filter(el=>el.name).map(el=>[el.name,el.value]):null;
  $('#main').innerHTML=({repositories:renderRepos,discover:renderDiscover,history:renderHistory,groups:renderGroups,overview:renderOverview,settings:renderSettings}[view.tab]||renderRepos)();
  if(settingsDraft){const replacement=$('#main form[data-form="settings"]');if(replacement){for(const [name,value] of settingsDraft){const control=replacement.elements.namedItem(name);if(control)control.value=value;}replacement.dataset.dirty='true';}}
  document.querySelectorAll('.group-column').forEach(column=>{const cards=column.querySelector('.group-cards');if(cards)cards.scrollTop=groupScroll.get(column.getAttribute('aria-labelledby'))||0;});
  const groupBoard=$('.group-board');if(groupBoard)groupBoard.scrollLeft=groupScrollLeft;
  if(view.tab==='discover')watchCandidates();
  if(focused){const replacement=document.getElementById(focused);if(replacement){replacement.focus();if(typeof cursor==='number' && replacement.type!=='number')try{replacement.setSelectionRange(cursor,cursor);}catch{}}}
}
function header(eyebrow,title,subtitle,actions=''){return `<header class="page-header"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p class="subtitle">${subtitle}</p></div><div class="actions">${actions}</div></header>${activityStrip()}`;}
function activityStrip(){const jobs=runningJobs();if(!jobs.length)return '';return `<div class="activity-strip"><span class="spinner" aria-hidden="true"></span><span>${esc(jobs[0].message||jobs[0].kind||'Working…')}</span><span>${jobs.length>1?`${jobs.length} jobs · `:''}<button class="text-link" data-action="activity">View activity</button></span></div>`;}
function stat(label,value,foot,accent=false){return `<div class="stat ${accent?'accent':''}"><div class="stat-label">${label}</div><div class="stat-value">${value}</div><div class="stat-foot">${foot}</div></div>`;}
function latestWorse(r){const t=trendRows(r);return t.length>1&&t[0].status!=='partial'&&t[1].status!=='partial'&&((t[0].status==='failed'&&t[1].status==='passed')||['failed','compile_errors','runtime_errors','timeouts'].some(k=>Number.isFinite(t[0][k])&&Number.isFinite(t[1][k])&&t[0][k]>t[1][k]));}

function renderOverview(){
  const repos=activeRepos(), never=repos.filter(r=>!latestRun(r)), gone=repos.filter(r=>r.upstream?.status==='gone');
  const archived=repos.filter(r=>r.upstream?.archived), pulled=repos.filter(r=>(r.locations||[]).some(l=>l.pulled&&!l.tested&&!l.dismissed));
  const worse=repos.filter(latestWorse), updates=repos.filter(r=>['updates','diverged'].includes(r.upstream?.status));
  const attention=[['worse','Worsened gate',worse,'Compared with the previous gate'],['pulled-untested','Ready to test',pulled,'Updated checkouts without results'],['never-run','Never run',never,'No recorded test result'],['gone','Unavailable upstream',gone,'Repository returned 404'],['archived-upstream','Archived upstream',archived,'No longer maintained upstream']];
  const needsAttention=new Set(attention.flatMap(([, , rows])=>rows.map(r=>r.id))).size;
  const changed=repos.filter(r=>r.upstream?.pushed_at).sort((a,b)=>String(b.upstream.pushed_at).localeCompare(String(a.upstream.pushed_at))).slice(0,6);
  const gates=new Map();
  for(const repo of repos)for(const run of trendRows(repo).filter(x=>x.status!=='partial')){
    const gate=gates.get(run.gate_label)||{date:run.started_at,repos:0,passed:0,failed:0,countsComplete:true,ids:new Set()};
    gate.repos++;gate.ids.add(repo.id);
    if(run.passed==null||run.failed==null)gate.countsComplete=false;else{gate.passed+=run.passed;gate.failed+=run.failed;}
    if(String(run.started_at)>String(gate.date))gate.date=run.started_at;
    gates.set(run.gate_label,gate);
  }
  const top=[...gates].sort((a,b)=>String(b[1].date||'').localeCompare(String(a[1].date||''))).slice(0,6);
  const jobPriority={running:0,queued:1,failed:2};
  const jobs=state.jobs.filter(j=>['running','queued','failed'].includes(j.status)&&!j.dismissed).sort((a,b)=>jobPriority[a.status]-jobPriority[b.status]||String(b.started_at||'').localeCompare(String(a.started_at||'')));
  const events=[...(state.events||[])].reverse().slice(0,6);
  const gateRows=top.map(([label,gate],index)=>{
    const previous=top[index+1]?.[1], comparable=previous&&gate.countsComplete&&previous.countsComplete&&[...gate.ids].sort().join('|')===[...previous.ids].sort().join('|');
    const delta=comparable?gate.failed-previous.failed:null;
    return `<li class="overview-row"><div class="overview-row-main"><button class="repo-name overview-row-title" data-action="gate-history" data-value="${esc(label)}">${esc(label)}</button><span class="overview-row-meta">${esc(date(gate.date))} · ${num(gate.repos)} repositories${delta!==null?` · ${delta===0?'Failures unchanged':`${delta>0?'+':''}${num(delta)} failures`}`:''}</span></div><div class="overview-row-side">${gate.countsComplete?`<strong>${num(gate.passed)} <span class="secondary">passed</span></strong><span class="${gate.failed?'text-error':'secondary'}">${num(gate.failed)} failed</span>`:'<span class="secondary">Counts incomplete</span>'}</div></li>`;
  }).join('');
  const changedRows=changed.map(repo=>`<li class="overview-row"><div class="overview-row-main"><button class="repo-name overview-row-title" data-action="repo-detail" data-id="${esc(repo.id)}">${esc(repo.name)}</button><span class="overview-row-meta">Pushed ${esc(date(repo.upstream.pushed_at))}${Number.isFinite(repo.upstream.behind)?` · ${num(repo.upstream.behind)} commits behind`:''}</span></div><div class="overview-row-side">${badge(repo.upstream.status||'unknown')}</div></li>`).join('');
  const jobRows=jobs.slice(0,5).map(job=>{
    const start=new Date(job.started_at).getTime(),end=job.finished_at?new Date(job.finished_at).getTime():Date.now();
    const duration=Number.isFinite(start)&&Number.isFinite(end)?`${Math.max(0,Math.floor((end-start)/1000))}s ${job.finished_at?'duration':'elapsed'}`:'';
    return `<li class="overview-row overview-job"><div class="overview-row-main"><div class="overview-row-title">${esc(job.kind||'Operation')} ${badge(job.status)}</div><p class="overview-row-meta">${esc(job.message||'No detail recorded.')}</p><span class="overview-row-meta">${esc(job.host?hostName(job.host):'Workspace')}${duration?` · ${duration}`:''}</span></div><div class="overview-row-side">${(job.status==='queued'||(job.status==='running'&&['Pull checkouts','Prepare checkout','Test update','Test updates'].includes(job.kind)))?`<button class="small quiet" data-action="cancel-job" data-id="${esc(job.id)}">Cancel</button>`:''}${job.status==='failed'?`<button class="small quiet" data-action="dismiss-job" data-id="${esc(job.id)}">Dismiss</button>`:''}</div></li>`;
  }).join('');
  return header('CORPUS / OVERVIEW','Corpus overview','Release evidence, upstream changes, and the work that needs your attention.','<button data-action="scan">Refresh inventory</button><button class="primary" data-action="check-all">Check upstream</button>')+
    `<section class="stats overview-stats" aria-label="Corpus overview summary">${stat('Active repositories',num(repos.length),`${num(state.hosts.length)} configured hosts`,true)}${stat('Need attention',num(needsAttention),'Repositories across the categories below')}${stat('Upstream updates',num(updates.length),'Compared with the tracked source revision')}${stat('Recorded gates',num(gates.size),`${num(state.settings.total_runs??state.runs.length)} observations in history`)}</section>
    <section class="overview-attention" aria-labelledby="attention-title"><div class="section-heading"><h2 id="attention-title">Needs attention</h2><span class="secondary">Open a category to review its repositories</span></div><div class="attention-grid">${attention.map(([value,label,rows,detail])=>`<button class="attention-card ${rows.length?'has-items':''}" data-action="attention" data-value="${value}"><span class="attention-label">${label}</span><strong class="attention-count">${num(rows.length)}</strong><span class="attention-detail">${detail}</span></button>`).join('')}</div></section>
    <div class="overview-grid"><section class="panel overview-panel"><div class="panel-heading"><h2>Latest gates</h2><button class="text-link" data-action="all-history">All history →</button></div>${gateRows?`<ul class="overview-list">${gateRows}</ul>`:'<p class="overview-empty">No labeled gate results have been imported yet.</p>'}<p class="panel-note">Linked, complete observations only. Changes are shown when the repository sets match.</p></section>
    <section class="panel overview-panel"><div class="panel-heading"><h2>Upstream activity</h2><button class="text-link" data-action="attention" data-value="updates">View updates →</button></div>${changedRows?`<ul class="overview-list">${changedRows}</ul>`:'<p class="overview-empty">Run an upstream check to see recent repository activity.</p>'}</section>
    <section class="panel overview-panel"><div class="panel-heading"><h2>Operations <span class="count-label">${num(jobs.length)}</span></h2><button class="text-link" data-action="activity">All activity →</button></div>${jobRows?`<ul class="overview-list">${jobRows}</ul>`:'<p class="overview-empty">No queued, running, or unresolved failed operations.</p>'}</section>
    <section class="panel overview-panel"><div class="panel-heading"><h2>Hosts</h2><a class="text-link" href="#settings">Manage →</a></div><div class="overview-hosts">${state.hosts.map(host=>`<div class="overview-host"><div class="overview-row-title">${esc(host.label||host.id)} ${badge(host.error?'error':host.last_scan?'current':'unknown',host.error?'Scan failed':host.last_scan?'Scanned':'Not checked')}</div><span class="overview-row-meta">${host.last_scan?`Last scan ${esc(time(host.last_scan))}`:'Inventory has not been checked'}</span></div>`).join('')||'<p class="overview-empty">Add a host in Settings to inventory existing checkouts.</p>'}</div></section>
    <section class="panel overview-panel overview-activity"><div class="panel-heading"><h2>Recent catalog activity</h2></div>${events.length?`<ul class="overview-list">${events.map(event=>`<li class="overview-row"><div class="overview-row-main"><span class="overview-row-title">${esc(event.action)}</span><span class="overview-row-meta">${esc(state.repositories.find(r=>r.id===event.repo_id)?.name||'Workspace')}</span></div><time class="overview-row-side secondary">${esc(time(event.at))}</time></li>`).join('')}</ul>`:'<p class="overview-empty">Catalog changes will appear here.</p>'}</section></div>`;
}

function renderRepos(){
  const active=activeRepos(),updates=active.filter(r=>['updates','diverged'].includes(r.upstream?.status)),unknown=active.filter(r=>!r.upstream?.checked_at).length;
  let repos=state.repositories.filter(r=>(!view.repoStatus||r.status===view.repoStatus)&&(!view.host||(r.locations||[]).some(l=>l.host===view.host))&&(!view.upstream||(view.upstream==='worse'?latestWorse(r):view.upstream==='pulled-untested'?(r.locations||[]).some(l=>l.pulled&&!l.tested&&!l.dismissed):view.upstream==='code-updates'?(['updates','diverged'].includes(r.upstream?.status)&&r.upstream?.changes?.touches_code!==false):view.upstream==='never-run'?!latestRun(r):view.upstream==='archived-upstream'?r.upstream?.archived:(r.upstream?.status||'unknown')===view.upstream))&&`${r.name} ${r.url} ${r.notes||''} ${(r.tags||[]).join(' ')}`.toLowerCase().includes(view.search.toLowerCase()));
  repos.sort((a,b)=>String(a.name||'').localeCompare(String(b.name||'')));view.filteredRepoIds=repos.map(r=>r.id);
  return header('CORPUS / REPOSITORIES','Your repository collection','Track what you have, what changed upstream, and how each revision performs with Glade.','<button data-action="scan">Refresh inventory</button><button class="primary" data-action="add-repo">+ Add repository</button>')+
    `<section class="stats" aria-label="Corpus summary">${stat('Active repositories',num(active.length),`${num(state.repositories.filter(r=>r.status==='archived').length)} archived · history preserved`,true)}${stat('Upstream updates',num(updates.length),`${num(unknown)} repositories not checked`)}${stat('New candidates',num(state.candidates.filter(c=>c.status==='new').length),`${num(state.queries.length)} saved discovery searches`)}${stat('Recorded runs',num(state.settings.total_runs??state.runs.length),'Repository revision × Glade version')}</section>
    <section class="panel"><div class="panel-heading"><h2>Repositories <span class="count-label">${num(repos.length)}</span></h2><div class="panel-actions"><button class="small quiet" data-action="select-filtered" ${repos.length?'':'disabled'}>Select all filtered</button>${selectedRepos.size?`<span class="selection-count">${num(selectedRepos.size)} selected</span><button class="small quiet" data-action="clear-selection">Clear selection</button>`:''}<button class="small" data-action="pull-selected" ${selectedRepos.size?'':'disabled'}>Pull selected</button><button class="small" data-action="test-selected" ${selectedRepos.size?'':'disabled'}>Test selected</button><button class="small" data-action="check-all">Check upstream</button></div></div>
    <div class="toolbar"><label class="sr-only" for="repo-search">Search repositories</label><input id="repo-search" class="search" data-filter="search" value="${esc(view.search)}" placeholder="Search repositories, notes, tags…"><label class="sr-only" for="repo-status">Repository status</label><select id="repo-status" data-filter="repoStatus">${[['active','Active'],['archived','Archived'],['candidate','Candidates'],['','All states']].map(([v,l])=>`<option value="${v}" ${view.repoStatus===v?'selected':''}>${l}</option>`).join('')}</select><label class="sr-only" for="repo-host">Host</label><select id="repo-host" data-filter="host"><option value="">All hosts</option>${state.hosts.map(h=>`<option value="${esc(h.id)}" ${view.host===h.id?'selected':''}>${esc(h.label||h.id)}</option>`).join('')}</select><label class="sr-only" for="repo-upstream">Upstream status</label><select id="repo-upstream" data-filter="upstream">${[['','Any upstream state'],['updates','Updates available'],['current','Up to date'],['diverged','Diverged'],['unknown','Not checked'],['error','Check failed'],['uncloned','No source revision'],['local-ahead','Local ahead'],['worse','Worsened gate'],['never-run','Never run'],['pulled-untested','Pulled, untested'],['code-updates','Updates touching code'],['archived-upstream','Archived upstream'],['gone','Gone (404)']].map(([v,l])=>`<option value="${v}" ${view.upstream===v?'selected':''}>${l}</option>`).join('')}</select></div>
    ${repos.length?`<div class="table-wrap" tabindex="0" role="region" aria-label="Repository table"><table class="repo-table"><colgroup><col class="select-col"><col class="name-col"><col class="location-col"><col class="upstream-col"><col class="result-col"><col class="collection-col"><col class="actions-col"></colgroup><thead><tr><th scope="col" class="select-cell"><span class="sr-only">Select</span></th><th scope="col">Repository</th><th scope="col">Host / revision</th><th scope="col">Upstream</th><th scope="col">Latest Glade result</th><th scope="col">Collection</th><th scope="col"><span class="sr-only">Open repository</span></th></tr></thead><tbody>${pageRows(repos,'repo').map(repoRow).join('')}</tbody></table></div><div class="table-footer"><span>${num(repos.length)} matching repositories · open one for full history</span>${pager('repo',repos.length)}</div>`:empty(view.search||view.host||view.upstream?'No matching repositories':'Your collection starts here','Add a repository URL or refresh inventory to find checkouts on your configured hosts.','<button class="primary" data-action="add-repo">Add repository</button>')}</section><p class="small-note">A repository’s source revision and the Glade revision are tracked separately. Missing historical references stay marked as unknown.</p>`;
}

function repoRow(r){
  const u=r.upstream||{},locs=r.locations||[],last=latestRun(r),loc=locs.find(l=>l.id===r.tracked_location_id)||locs[0];
  const check=last&&(r.runs||[]).find(x=>x.phase==='check'&&x.started_at===last.started_at);
  return `<tr><td class="select-cell"><input id="select-${esc(r.id)}" type="checkbox" data-select-repo="${esc(r.id)}" aria-label="Select ${esc(r.name)}" ${selectedRepos.has(r.id)?'checked':''}></td><td class="repo-cell"><div class="repo-identity"><button class="repo-name repo-primary" data-action="repo-detail" data-id="${esc(r.id)}">${esc(r.name||r.url||'Unnamed repository')}</button><div class="repo-meta">${(r.tags||[]).length?`<div class="tags">${r.tags.slice(0,3).map(t=>`<span class="tag">${esc(t)}</span>`).join('')}${r.tags.length>3?`<span class="tag">+${r.tags.length-3}</span>`:''}</div>`:`<span class="secondary">${r.tier&&r.tier!=='unassigned'?`Group ${esc(r.tier)}`:'Unassigned'}</span>`}</div></div></td><td class="location-cell">${loc?`<span>${esc(hostName(loc.host))}${locs.length>1?` <span class="muted">+${locs.length-1}</span>`:''}</span><span class="secondary mono">${esc(short(loc.head))}</span>`:'<span class="muted">No checkout</span>'}</td><td class="upstream-cell">${badge(u.status||'unknown')}<span class="secondary">${u.checked_at?`Checked ${esc(date(u.checked_at))}${Date.now()-new Date(u.checked_at).getTime()>7*864e5?' · stale':''}`:'Check when ready'}</span></td><td class="result-cell">${last?`${runBadge(last.status)}<span class="secondary">${esc(last.gate_label||last.glade_version||short(last.glade_sha))}</span>${check?`<span class="secondary">Check: ${esc(runLabel(check.status))}</span>`:''}`:'<span class="muted">No recorded run</span>'}</td><td class="collection-cell">${badge(r.status||'active')}</td><td class="row-actions"><button class="quiet small" data-action="repo-detail" data-id="${esc(r.id)}" aria-label="Open ${esc(r.name)}">↗</button></td></tr>`;
}
function watchCandidates(){
 if(projectObserver)projectObserver.disconnect();
 if(projectStopped||projectJob||typeof IntersectionObserver==='undefined')return;
 projectObserver=new IntersectionObserver(entries=>{for(const entry of entries){const id=entry.target.dataset.projectCandidate;const c=state.candidates.find(x=>x.id===id);if(!entry.isIntersecting||!c||c.status!=='new'||(c.salesforce_project&&c.salesforce_project!=='unknown')||projectAttempted.has(id)||projectJob)continue;projectAttempted.add(id);projectJob='starting';api(`/api/candidates/${encodeURIComponent(id)}/project-check`,{}).then(result=>{projectJob=result.job;load();}).catch(()=>{projectJob=null;projectStopped=true;});projectObserver.disconnect();break;}},{rootMargin:'100px'});
 document.querySelectorAll('[data-project-candidate]').forEach(el=>projectObserver.observe(el));
}
function renderDiscover(){let candidates=state.candidates.filter(c=>(!view.candidateStatus||c.status===view.candidateStatus)&&(!view.query||c.query_id===view.query||c.query_ids?.includes(view.query))&&(view.projectFilter!=='confirmed'||c.salesforce_project!=='absent')&&`${c.full_name} ${c.description||''}`.toLowerCase().includes(view.candidateSearch.toLowerCase()));return header('CORPUS / DISCOVERY','Find your next test case','Save GitHub searches and review fresh candidates before adding them to your collection.','<button class="primary" data-action="add-query">+ New search</button>')+
  `<div class="two-col"><aside><section class="panel queries"><div class="panel-heading"><h2>Saved searches</h2><button class="text-link" data-action="filter-query" data-id="">All</button></div>${state.queries.length?state.queries.map(q=>`<div class="query ${view.query===q.id?'selected':''}"><div class="query-title"><button class="repo-name" data-action="filter-query" data-id="${esc(q.id)}">${esc(q.name||'Saved search')}</button><button class="quiet small" data-action="edit-query" data-id="${esc(q.id)}" aria-label="Edit ${esc(q.name)}">Edit</button></div><div class="query-text">${esc(q.query)}</div><div class="query-meta">Checked ${esc(time(q.last_checked))}${q.total_count!==undefined?` · ${num(q.returned??50)} of ${num(q.total_count)} matches · 50-result limit`:''}${q.incomplete?' · GitHub marked results incomplete':''}</div>${q.error?`<p class="small-note">${esc(q.error)}</p>`:''}<button class="small" data-action="run-query" data-id="${esc(q.id)}">Run search ↗</button></div>`).join(''):empty('No saved searches','Try language:Apex, a Salesforce topic, or a specific organization.','<button class="small" data-action="add-query">Create search</button>')}</section><p class="small-note">Search results are candidates, not compatibility claims. Review scope, license, activity, and test coverage before adding a project.</p></aside><section><div class="panel"><div class="toolbar"><label class="sr-only" for="candidate-search">Search candidates</label><input id="candidate-search" class="search" data-filter="candidateSearch" value="${esc(view.candidateSearch)}" placeholder="Filter candidates…"><select aria-label="Candidate status" id="candidate-status" data-filter="candidateStatus">${[['new','New candidates'],['dismissed','Dismissed'],['added','Added'],['','All candidates']].map(([v,l])=>`<option value="${v}" ${view.candidateStatus===v?'selected':''}>${l}</option>`).join('')}</select><select data-filter="projectFilter" aria-label="Salesforce project"><option value="confirmed" ${view.projectFilter==='confirmed'?'selected':''}>Confirmed or unknown</option><option value="all" ${view.projectFilter==='all'?'selected':''}>All projects</option></select></div><div class="table-footer"><span>${candidates.length} candidates${view.query?' in selected search':''}</span>${view.query?'<button class="text-link" data-action="filter-query" data-id="">Clear search filter</button>':''}</div></div><div class="candidate-grid">${candidates.length?pageRows(candidates,'candidate').map(c=>`<article class="candidate" data-project-candidate="${esc(c.id)}"><div class="candidate-title"><a href="${esc(url(c.url))}" target="_blank" rel="noopener noreferrer">${esc(c.full_name||c.name)} ↗</a>${badge(c.status)} ${badge(c.salesforce_project==='confirmed'?'current':'unknown',c.salesforce_project==='confirmed'?'Salesforce project':c.salesforce_project==='absent'?'No project file':'Project unknown')}</div><p>${esc(c.description||'No description supplied.')}</p><div class="candidate-bottom"><div class="candidate-meta"><span>☆ ${num(c.stars)}</span><span>${esc(c.language||'Language unknown')}</span><span>${esc(c.license||'License unknown')}</span><span>Updated ${esc(date(c.pushed_at))}</span></div><div class="actions">${!c.salesforce_project||c.salesforce_project==='unknown'?`<button class="small" data-action="check-project" data-id="${esc(c.id)}">Check project</button>`:''}${c.status==='new'?`<button class="small quiet" data-action="dismiss-candidate" data-id="${esc(c.id)}">Dismiss</button><button class="small primary" data-action="add-candidate" data-id="${esc(c.id)}">Add to corpus</button>`:c.status==='dismissed'?`<button class="small" data-action="restore-candidate" data-id="${esc(c.id)}">Review again</button>`:'<span class="small-note">In your collection</span>'}</div></div></article>`).join(''):empty('Nothing waiting for review','Run a saved search to find projects, or change your candidate filter.')}</div><div class="table-footer">${pager('candidate',candidates.length)}</div></section></div>`;}
function runTable(runs,compact=false){return `<div class="table-wrap"><table><thead><tr>${compact?'':'<th>Repository</th>'}<th>Gate / Glade</th>${runs.some(r=>r.repo_sha||r.api_version)?'<th>Source revision</th>':''}<th>Result</th><th>Tests P / F / S</th><th>Recorded</th><th></th></tr></thead><tbody>${runs.map(r=>`<tr>${compact?'':`<td><button class="repo-name" data-action="repo-detail" data-id="${esc(r.repo_id)}">${esc(r.repo_name||state.repositories.find(p=>p.id===r.repo_id)?.name||'Unmatched repository')}</button><span class="secondary">${esc(hostName(r.host))}</span></td>`}<td>${esc(r.gate_label||r.glade_version||'Unlabeled gate')}${r.glade_sha?`<span class="secondary mono">${esc(short(r.glade_sha))}</span>`:''}</td>${runs.some(x=>x.repo_sha||x.api_version)?`<td>${r.repo_sha?`<span class="mono">${esc(short(r.repo_sha))}</span>`:''}${r.api_version?`<span class="secondary">API ${esc(r.api_version)}</span>`:''}</td>`:''}<td>${runBadge(r.status||'unknown')}${r.result_status?`<span class="secondary">Observed: ${esc(runLabel(r.result_status))}</span>`:''}</td><td class="nowrap"><span>${num(r.passed)}</span> <span class="muted">/</span> <span>${num(r.failed)}</span> <span class="muted">/</span> <span>${num(r.skipped)}</span></td><td class="nowrap">${esc(date(r.started_at))}<span class="secondary">${esc(r.identity_match==='unmatched'?'Unmatched identity':r.identity_match==='ambiguous'?'Ambiguous identity':r.provenance||'Imported evidence')}</span></td><td><button class="quiet small" data-action="run-detail" data-id="${esc(r.id)}">Details</button></td></tr>`).join('')}</tbody></table></div>`;}
function renderHistory(){const runs=historyData.runs||[],total=historyData.total||0,selectedRepo=state.repositories.find(r=>r.id===view.historyRepo);return header('CORPUS / EVIDENCE','The history behind every result','Keep repository revisions, Glade versions, and observed outcomes together.','<button data-action="import-bootstrap">Import saved scan history</button><button data-action="record-run">Record result</button><button class="primary" data-action="import">Import evidence</button>')+`<div class="notice">History records observations from existing reports. An incomplete run or missing revision is shown explicitly; importing evidence does not run tests.</div>${historyData.error?`<div class="notice error">${esc(historyData.error)} <button class="text-link" data-action="history-reload">Try again</button></div>`:''}<section class="panel"><div class="panel-heading"><h2>Run history <span class="count-label">${num(total)}</span></h2>${historyData.loading?'<span class="spinner" aria-label="Loading history"></span>':''}</div><div class="toolbar"><input class="search" id="history-search" data-filter="historySearch" aria-label="Search run history" value="${esc(view.historySearch)}" placeholder="Search repository, Glade version, revision…"><select data-filter="historyPhase" aria-label="History phase">${[["test","Test phase"],["check","Check phase"],["","All phases"]].map(([v,l])=>`<option value="${v}" ${view.historyPhase===v?"selected":""}>${l}</option>`).join("")}</select><select id="history-status" data-filter="historyStatus" aria-label="Result status">${[['','All results'],['passed','Passed'],['failed','Failed'],['partial','Partial'],['incomplete','Incomplete'],['error','Execution error'],['timeout','Timed out'],['unknown','Outcome unknown']].map(([v,l])=>`<option value="${v}" ${view.historyStatus===v?'selected':''}>${l}</option>`).join('')}</select>${view.historyRepo?`<span class="filter-count">${esc(selectedRepo?.name||'Selected repository')}</span><button class="text-link" data-action="clear-history-repo">Clear repository</button>`:''}</div>${runs.length?runTable(runs):historyData.loading?'<div class="empty">Loading history…</div>':empty('No history in this view','Import existing summary reports or record an observed result with its repository and Glade revision.','<button class="primary" data-action="import">Import evidence</button>')}<div class="table-footer"><span>P = passed · F = failed · S = skipped · Unknown is different from zero</span>${pager('history',total)}</div></section>`;}
function trendRows(repo){const map=new Map();for(const r of [...(repo.runs||[])].filter(x=>x.phase==='test'&&x.gate_label).sort((a,b)=>String(b.started_at||'').localeCompare(String(a.started_at||'')))){const old=map.get(r.gate_label);if(!old||(old.status==='partial'&&!old.conflict&&r.status!=='partial'))map.set(r.gate_label,r);else if(!old.conflict&&old.status!=='partial'&&r.status!=='partial'&&signature(old)!==signature(r))map.set(r.gate_label,{...old,status:'partial',conflict:true,passed:null,failed:null,compile_errors:null,runtime_errors:null,timeouts:null,wall_s:null});}return [...map.values()].sort((a,b)=>String(b.started_at||'').localeCompare(String(a.started_at||'')));}
function signature(r){return r?JSON.stringify([r.status,r.passed,r.failed,r.compile_errors,r.runtime_errors,r.timeouts]):'';}
function trendTable(runs){const rows=trendRows({runs});return `<section class="detail-section"><h3>Gate trend · ${rows.length}</h3>${rows.length?`<div class="table-wrap"><table><thead><tr><th>Gate</th><th>P / F</th><th>Compile</th><th>Runtime</th><th>Timeouts</th><th>Status</th><th>Wall</th><th>Change</th></tr></thead><tbody>${rows.map((r,i)=>`<tr><td>${esc(r.gate_label)} <span class="mono">${esc(r.glade_sha?short(r.glade_sha):'')}</span></td><td>${num(r.passed)} / ${num(r.failed)}</td><td>${num(r.compile_errors)}</td><td>${num(r.runtime_errors)}</td><td>${num(r.timeouts)}</td><td>${runBadge(r.status)}${r.conflict?'<span class="secondary">Conflicting observations</span>':''}</td><td>${num(r.wall_s)}</td><td>${i+1<rows.length?(r.status==='partial'||rows[i+1].status==='partial'?'Incomparable':signature(r)!==signature(rows[i+1])?'Changed':'Same'):'—'}</td></tr>`).join('')}</tbody></table></div>`:'<p>No labeled test gates.</p>'}</section>`;}

function renderGroups(){
  const tiers=state.settings.tiers||{},canMove=!!tiers.path;
  const gateDates=new Map();for(const repo of state.repositories)for(const row of trendRows(repo)){if(String(row.started_at||'')>String(gateDates.get(row.gate_label)||''))gateDates.set(row.gate_label,row.started_at||'');else if(!gateDates.has(row.gate_label))gateDates.set(row.gate_label,'');}
  const gateLabels=[...gateDates].sort((a,b)=>String(b[1]).localeCompare(String(a[1]))||a[0].localeCompare(b[0])).map(([label])=>label);
  const repos=state.repositories.filter(r=>`${r.name} ${(r.tags||[]).join(' ')}`.toLowerCase().includes(view.groupSearch.toLowerCase())&&(!view.groupUpstream||(view.groupUpstream==='archived-upstream'?r.upstream?.archived:(r.upstream?.status||'unknown')===view.groupUpstream))&&(!view.groupResult||(view.groupResult==='never'?!latestRun(r):latestRun(r)?.status===view.groupResult)));
  const options=value=>`<option value="">Choose gate</option>${gateLabels.map(label=>`<option value="${esc(label)}" ${label===value?'selected':''}>${esc(label)}</option>`).join('')}`;
  const shared=state.repositories.map(repo=>{const rows=trendRows(repo);return {repo,a:rows.find(x=>x.gate_label===view.gateA),b:rows.find(x=>x.gate_label===view.gateB)};}).filter(x=>x.a&&x.b&&x.a.status!=='partial'&&x.b.status!=='partial');
  const changes=shared.filter(x=>signature(x.a)!==signature(x.b));
  let comparison='Choose two gates to compare their recorded test results.';
  if(view.gateA&&view.gateB){
    if(view.gateA===view.gateB)comparison='Choose two different gates to compare.';
    else if(!shared.length)comparison='No shared, complete repository results for these gates.';
    else if(!changes.length)comparison=`No changed results across ${num(shared.length)} comparable repositories.`;
    else comparison='';
  }
  const board=[['A','Every PR'],['B','Nightly'],['C','Release candidate'],['unassigned','Not assigned']].map(([tier,cadence])=>{
    const group=repos.filter(r=>(r.tier||'unassigned').toLowerCase()===tier.toLowerCase()).sort((a,b)=>String(a.name||'').localeCompare(String(b.name||'')));
    return `<section class="group-column" ${canMove?`data-drop-tier="${tier}"`:''} aria-labelledby="group-${tier}-title"><div class="group-column-header"><div><h2 id="group-${tier}-title">${tier==='unassigned'?'Unassigned':`Group ${tier}`}</h2><span class="group-cadence">${cadence}</span></div><span class="group-count">${num(group.length)}</span></div><div class="group-cards" tabindex="0" role="region" aria-label="${tier==='unassigned'?'Unassigned repositories':`Group ${tier} repositories`}">${group.map(repo=>`<article class="group-card" draggable="${canMove?'true':'false'}" data-repo="${esc(repo.id)}"><div class="group-card-heading"><button class="repo-name" data-action="repo-detail" data-id="${esc(repo.id)}">${esc(repo.name)}</button></div><div class="group-card-status">${badge(repo.upstream?.status||'unknown')} ${latestRun(repo)?runBadge(latestRun(repo).status):'<span class="secondary">Never run</span>'}</div><div class="group-card-footer"><span class="secondary">${num(trendRows(repo).length)} gates</span><label class="group-select" for="group-select-${esc(repo.id)}"><span>Group</span><select id="group-select-${esc(repo.id)}" data-tier-repo="${esc(repo.id)}" aria-label="Group for ${esc(repo.name)}" ${canMove?'':'disabled'}>${['A','B','C','unassigned'].map(value=>`<option value="${value}" ${value.toLowerCase()===(repo.tier||'unassigned').toLowerCase()?'selected':''}>${value==='unassigned'?'Unassigned':value}</option>`).join('')}</select></label></div></article>`).join('')||'<p class="group-empty">No matching repositories.</p>'}</div></section>`;
  }).join('');
  return header('CORPUS / GROUPS','Release groups','Organize repository coverage by release cadence and compare gate results.')+
    `<div class="notice group-guidance">Use the group selector or drag a card to move a repository. B moves to C after two releases without a NEW; a NEW moves the repository up.</div>${!canMove?'<p class="notice warning">Configure the tiers file in <a href="#settings">Settings</a> to enable group changes.</p>':''}
    <section class="panel groups-filter-panel"><div class="toolbar groups-toolbar"><div class="filter-field group-search-field"><label for="group-search">Search repositories</label><input id="group-search" class="search" data-filter="groupSearch" placeholder="Search names or tags…" value="${esc(view.groupSearch)}"></div><div class="filter-field"><label for="group-upstream">Upstream status</label><select id="group-upstream" data-filter="groupUpstream"><option value="">All upstream states</option>${['current','updates','diverged','unknown','error','gone','archived-upstream'].map(value=>`<option value="${value}" ${view.groupUpstream===value?'selected':''}>${esc(labelsFor(value))}</option>`).join('')}</select></div><div class="filter-field"><label for="group-result">Latest result</label><select id="group-result" data-filter="groupResult"><option value="">All results</option>${[['passed','Passed'],['failed','Failed'],['partial','Partial'],['never','Never run']].map(([value,label])=>`<option value="${value}" ${view.groupResult===value?'selected':''}>${label}</option>`).join('')}</select></div><span class="filter-count">${num(repos.length)} repositories</span></div></section>
    <div class="group-board">${board}</div>
    <section class="panel gate-comparison"><div class="panel-heading"><h2>Compare gates</h2><span class="secondary">Complete observations shared by both gates</span></div><div class="gate-controls"><div class="filter-field"><label for="gate-a">Baseline gate</label><select id="gate-a" data-filter="gateA">${options(view.gateA)}</select></div><span class="gate-direction" aria-hidden="true">→</span><div class="filter-field"><label for="gate-b">Comparison gate</label><select id="gate-b" data-filter="gateB">${options(view.gateB)}</select></div></div>${comparison?`<p class="comparison-empty">${comparison}</p>`:`<div class="comparison-summary">${num(changes.length)} changed of ${num(shared.length)} comparable repositories</div><ul class="gate-change-list">${changes.map(({repo,a,b})=>`<li class="gate-change-row"><button class="repo-name" data-action="repo-detail" data-id="${esc(repo.id)}">${esc(repo.name)}</button><div class="gate-result">${runBadge(a.status)}<span class="secondary">${num(a.passed)} passed / ${num(a.failed)} failed</span></div><span class="gate-direction" aria-hidden="true">→</span><div class="gate-result">${runBadge(b.status)}<span class="secondary">${num(b.passed)} passed / ${num(b.failed)} failed</span></div></li>`).join('')}</ul>`}</section>`;
}
function labelsFor(x){return x==='archived-upstream'?'Archived upstream':labels[x]||x;}
function renderSettings(){return header('CORPUS / WORKSPACE','Hosts & settings','Connect existing corpus locations. Keep the catalog local and repository files on their hosts.','<button class="primary" data-action="add-host">+ Add host</button>')+`<section class="panel panel-body"><h2>Groups file</h2><form data-form="settings"><div class="form-error" role="alert" hidden></div>${field('Tiers JSON file','tiers_file',state.settings.tiers?.path||'')}${field('Glade binary on host','glade_binary',state.settings.glade_binary||'')}${field('Glade build commit SHA','glade_sha',state.settings.glade_sha||'',{help:'Supply the source commit used to build this binary.'})}${field('Corpus runner binary on host','runner_binary',state.settings.runner_binary||'')}${selectField('Default host','default_host',[['','Choose a host'],...state.hosts.map(h=>[h.id,h.label||h.id])],state.settings.default_host||'')}<button type="submit">Save settings</button></form>${state.settings.tiers?.error?`<p class="notice error">${esc(state.settings.tiers.error)}</p>`:''}</section><div class="host-grid">${state.hosts.map(h=>`<section class="host-card"><div class="host-top"><h2>${esc(h.label||h.id)}</h2>${badge(h.error?'error':h.last_scan?'current':'unknown',h.error?'Scan failed':h.last_scan?'Scanned':'Not scanned')}</div><dl class="definition"><dt>Connection</dt><dd>${esc(h.ssh||'This computer')}</dd><dt>Inventory roots</dt><dd>${(h.roots||[]).map(p=>`<div class="path">${esc(p)}</div>`).join('')||'Not configured'}</dd><dt>New checkouts</dt><dd class="path">${esc(h.managed_root||'Not configured')}</dd><dt>Last scan</dt><dd>${esc(time(h.last_scan))}</dd></dl>${h.error?`<div class="notice error">${esc(h.error)}</div>`:''}<div class="actions"><button class="small" data-action="scan-host" data-id="${esc(h.id)}">Refresh inventory</button><button class="small quiet" data-action="edit-host" data-id="${esc(h.id)}">Edit host</button></div></section>`).join('')||empty('Add your first host','Use an SSH alias for a remote host, or leave it empty for existing local checkouts.','<button class="primary" data-action="add-host">Add host</button>')}</div><div class="subsection"><h2>Catalog & workflow</h2></div><section class="panel"><div class="panel-body settings-info"><div><h3>Portable metadata</h3><p>Export the catalog, recorded observations, and search criteria as JSON. Repository source files are not included.</p></div><button data-action="export">Export catalog</button></div></section><section class="panel"><div class="panel-body"><h3>What each action does</h3><dl class="definition settings-definition"><dt>Inventory</dt><dd>Reads repository metadata from configured roots.</dd><dt>Upstream checks</dt><dd>Checks GitHub without changing any checkout.</dd><dt>Updated checkout</dt><dd>Prepares a separate revision on a configured host. Existing checkouts remain intact.</dd><dt>Archive</dt><dd>Removes a repository from the active collection. Its checkouts and run history stay available.</dd><dt>Authentication</dt><dd>${state.settings.github_authenticated?'Authenticated GitHub connection available.':'Using public GitHub access; rate limits may restrict checks. Configure server-side GitHub authentication for larger collections.'} Credentials stay on the server.</dd><dt>Catalog directory</dt><dd class="path">${esc(state.settings.data_directory||'Not reported')}</dd></dl></div></section>`;}
function openModal(title,description,body,{form='',submit='Save',extra=''}={}){$('#modal').dataset.view='';$('#modal-content').innerHTML=`${form?`<form data-form="${esc(form)}">`:''}<div class="modal-header"><div><h2 id="modal-title">${esc(title)}</h2>${description?`<p>${esc(description)}</p>`:''}</div><button type="button" class="close" data-action="close-modal" aria-label="Close">×</button></div><div class="modal-body"><div class="form-error" id="form-error" hidden></div>${body}</div><div class="modal-footer">${extra}<button type="button" data-action="close-modal">${form?'Cancel':'Close'}</button>${form?`<button class="primary" type="submit">${esc(submit)}</button>`:''}</div>${form?'</form>':''}`;if(!$('#modal').open)$('#modal').showModal();}
function closeModal(){$('#modal').close();}
function openDetail(id){const repo=state.repositories.find(r=>r.id===id);if(!repo){notify('This result is not linked to a catalog repository.',true);return;}view.detail=id;renderDetail(id);if(!$('#detail').open)$('#detail').showModal();}
function updateComparison(repo,loc){const rows=repo.runs||[], update=rows.find(x=>x.repo_sha===loc.head&&x.phase==='test'&&x.gate_label?.startsWith('update-'));if(!update)return '';const base=rows.find(x=>x.repo_sha===repo.pin&&x.glade_sha&&x.glade_sha===update.glade_sha&&x.phase==='test');if(!base)return '<p class="small-note">No pin baseline on the same Glade revision.</p>';let summary='Counts only',names='';if(Array.isArray(base.failed_tests)&&Array.isArray(update.failed_tests)){const before=new Set(base.failed_tests),after=new Set(update.failed_tests),fixed=[...before].filter(x=>!after.has(x)),added=[...after].filter(x=>!before.has(x));summary=`Update fixes ${fixed.length}, breaks ${added.length}`;names=`<p>Fixed: ${fixed.map(esc).join(', ')||'None'}<br>New failures: ${added.map(esc).join(', ')||'None'}</p>`;}return `<p>${esc(summary)} · pin ${num(base.passed)} / ${num(base.failed)}, compile ${num(base.compile_errors)}, ${num(base.wall_s)}s → update ${num(update.passed)} / ${num(update.failed)}, compile ${num(update.compile_errors)}, ${num(update.wall_s)}s</p>${names}`;}
function renderDetail(id){const r=state.repositories.find(x=>x.id===id);if(!r)return;const u=r.upstream||{},runs=[...(r.runs||state.runs.filter(x=>x.repo_id===id))].sort((a,b)=>String(b.started_at||'').localeCompare(String(a.started_at||'')));$('#detail-content').innerHTML=`<div class="modal-header"><div><div class="detail-title-row"><h2 id="detail-title">${esc(r.name||r.url)}</h2>${badge(r.status)}</div><p><a href="${esc(url(r.url))}" target="_blank" rel="noopener noreferrer">${esc(r.url||'No upstream URL')} ↗</a></p><div class="detail-header-actions"><button class="small" data-action="check-repo" data-id="${esc(id)}">Check upstream</button><button class="small primary" data-action="snapshot" data-id="${esc(id)}">Prepare updated checkout</button><button class="small" data-action="edit-repo" data-id="${esc(id)}">Edit details</button><button class="small quiet" data-action="archive-repo" data-id="${esc(id)}">${r.status==='archived'?'Restore to active':'Archive repository'}</button></div></div><button class="close" data-action="close-detail" aria-label="Close repository">×</button></div><div class="modal-body"><div class="detail-grid"><div><section class="detail-section"><h3>Checkouts & revisions</h3>${(r.locations||[]).length?r.locations.map(l=>`<div class="checkout"><div class="checkout-head"><strong>${esc(hostName(l.host))}</strong>${badge(l.dirty===true?'partial':l.dirty===false?'current':'unknown',l.dirty===true?'Local changes':l.dirty===false?'Clean':'State unknown')}</div><div class="path">${esc(l.path)}</div><p class="secondary"><span class="mono">${esc(l.head||'Unknown source revision')}</span></p><span class="secondary">${esc(l.branch||(l.head?'Detached revision':'No Git revision'))} · scanned ${esc(time(l.scanned_at))}</span>${l.pulled?`<p class="notice">Pulled ${esc(time(l.pulled_at))} · ${l.tested?'Tested':'Untested'} · ${l.size_bytes!=null?num(Math.round(l.size_bytes/1048576))+' MiB':'Size unavailable'}</p>${l.ownership_token?`<button class="small" data-action="delete-pull" data-id="${esc(r.id)}" data-location="${esc(l.id)}">Delete checkout</button>`:''}${l.dismissed?'<span class="secondary">Pin kept</span>':`<button class="small" data-action="test-update" data-id="${esc(r.id)}" data-location="${esc(l.id)}">Test update</button><button class="small" data-action="accept-pin" data-id="${esc(r.id)}" data-location="${esc(l.id)}">Accept as pin</button><button class="small" data-action="keep-pin" data-id="${esc(r.id)}" data-location="${esc(l.id)}">Keep pin</button>`}${updateComparison(r,l)}`:''}<div class="checkout-track">${r.tracked_location_id===l.id?'<span class="pill current">Tracked for upstream checks</span>':`<button class="small" data-action="track-checkout" data-id="${esc(r.id)}" data-location="${esc(l.id)}">Track this checkout</button>`}</div></div>`).join(''):'<p>No checkout recorded. Prepare a checkout on a configured host when ready.</p>'}</section></div><div><section class="detail-section"><h3>Upstream</h3>${badge(u.status||'unknown')}${u.stale_pin?'<p class="notice">Pin changed; check upstream again.</p>':''}<dl class="definition">${r.pin?`<dt>Pin</dt><dd class="mono">${esc(short(r.pin))}</dd>`:''}<dt>Checked</dt><dd>${esc(time(u.checked_at))}</dd><dt>Compared from ${esc(u.base_kind||'tracked checkout')}</dt><dd class="mono">${esc(u.base_sha?short(u.base_sha):'No source revision')}</dd><dt>Latest revision</dt><dd class="mono">${esc(u.sha?short(u.sha):'Unknown')}</dd><dt>Default branch</dt><dd>${esc(u.default_branch||'Unknown')}</dd>${u.behind!==undefined?`<dt>Commits behind</dt><dd>${num(u.behind)}</dd>`:''}<dt>Last activity</dt><dd>${esc(date(u.pushed_at))}</dd></dl>${u.changes?`<div><h4>Changes since ${esc(u.base_kind||'tracked checkout')}</h4>${u.changes.incomplete?'<p class="notice">GitHub returned a partial comparison.</p>':''}${u.changes.commits.map(c=>`<p><a href="${esc(url(c.url))}" target="_blank" rel="noopener noreferrer">${esc(short(c.sha))} ${esc(c.message)}</a> · ${esc(date(c.date))}</p>`).join('')}${Object.entries(u.changes.files).filter(([,items])=>items.length).map(([group,items])=>`<p><strong>${esc(group)}</strong>: ${items.map(x=>esc(x.name)).join(', ')}</p>`).join('')}</div>`:''}${u.compare_url?`<a class="text-link" href="${esc(url(u.compare_url))}" target="_blank" rel="noopener noreferrer">View upstream changes ↗</a>`:''}${u.error?`<p class="notice error">${esc(u.error)}</p>`:''}</section><section class="detail-section"><h3>Organization</h3><dl class="definition"><dt>Tier</dt><dd>${esc(r.tier||'Unclassified')}</dd><dt>Tags</dt><dd>${esc((r.tags||[]).join(', ')||'None')}</dd></dl><p>${esc(r.notes||'Add notes about coverage, dependencies, or why this repository belongs in the corpus.')}</p></section></div></div><section class="detail-section"><h3>Timeline</h3>${[...state.events.filter(e=>e.repo_id===r.id),...runs.filter(x=>x.phase==='test').map(x=>({at:x.started_at,action:'gate '+(x.gate_label||'unlabeled')+' · '+runLabel(x.status)}))].sort((a,b)=>String(b.at||'').localeCompare(String(a.at||''))).slice(0,40).map(e=>`<p>${esc(time(e.at))} · ${esc(e.action)}${e.detail?` · ${esc(e.detail)}`:''}</p>`).join('')||'<p>No activity recorded.</p>'}</section>${trendTable(runs)}<section class="detail-section"><h3>Glade run history · ${r.run_count??runs.length}</h3>${runs.length?runTable(runs.slice(0,60),true):'<p>No imported or manually recorded results for this repository.</p>'}<p class="history-note">${runs.length>60?`Showing the latest 60 of ${runs.length} observations. `:''}Results refer to the revision recorded at run time. The current checkout does not fill in a missing historical revision.</p><button class="small" data-action="repo-history" data-id="${esc(id)}">View all history →</button></section></div>`;}
function repoForm(id){const r=state.repositories.find(r=>r.id===id);if(!r)return;openModal('Edit repository','Keep the context that makes this repository useful.',`<input type="hidden" name="id" value="${esc(id)}">${field('Tags','tags',(r.tags||[]).join(', '),{help:'Separate tags with commas.'})}${field('Notes','notes',r.notes||'',{textarea:true})}${selectField('Collection status','status',[['active','Active'],['archived','Archived'],['candidate','Candidate']],r.status)}`,{form:'repo-edit'});}
function queryForm(id){const q=state.queries.find(q=>q.id===id)||{};openModal(id?'Edit saved search':'New saved search','Use GitHub repository search qualifiers to describe candidates.',`<input type="hidden" name="id" value="${esc(id||'')}">${field('Search name','name',q.name||'',{required:true,placeholder:'Active Apex libraries'})}${field('GitHub query','query',q.query||'language:Apex archived:false fork:false',{textarea:true,required:true,help:'Examples: topic:salesforce · stars:>5 · pushed:>2026-01-01. Results are bounded to keep checks lightweight.'})}`,{form:'query',extra:id?`<button type="button" class="danger quiet" data-action="delete-query" data-id="${esc(id)}">Delete search</button>`:''});}
function hostForm(id){const h=state.hosts.find(h=>h.id===id)||{};openModal(id?'Edit host':'Add host','Inventory reads metadata from existing checkouts. New checkouts use a separate managed directory.',`<input type="hidden" name="id" value="${esc(id||'')}">${field('Display name','label',h.label||'',{required:true,placeholder:'Corpus host'})}${field('SSH alias','ssh',h.ssh||'',{help:'Leave empty for this computer. Uses your existing SSH configuration.'})}${field('Inventory roots','roots',(h.roots||[]).join('\n'),{textarea:true,required:true,help:'One absolute directory per line.'})}${field('Managed checkout directory','managed_root',h.managed_root||'',{help:'A host-side directory for new, separate revisions. Leave empty to disable checkout creation.'})}`,{form:'host'});}
function importForm(){openModal('Import run evidence','Read an existing report on its host. Only summary metadata is added to this catalog.',`${selectField('Report host','host',[['','This computer'],...state.hosts.filter(h=>h.ssh).map(h=>[h.id,h.label||h.id])])}${field('Report path','path','',{required:true,placeholder:'Absolute path to aggregate .json or .jsonl file'})}<div class="form-row">${field('Glade version','glade_version','',{placeholder:'Optional, e.g. 0.3.2'})}${field('Glade commit','glade_sha','',{placeholder:'Optional full commit SHA'})}</div><div class="notice">Supply a Glade version or commit only if it is known for this report. Missing historical references remain unknown.</div>`,{form:'import',submit:'Import evidence'});}
function runForm(){openModal('Record observed result','Use this for a result you already have. This action does not launch validation.',`${selectField('Repository','repo_id',state.repositories.map(r=>[r.id,r.name||r.url]))}<div class="form-row">${field('Glade version','glade_version')}${field('Glade commit','glade_sha')}</div>${field('Repository commit at run time','repo_sha','',{help:'Leave empty if the source revision was not recorded.'})}<div class="form-row">${field('API version','api_version')}${selectField('Outcome','status',[['passed','Passed'],['failed','Failed'],['incomplete','Incomplete'],['unknown','Unknown']],'unknown')}</div><div class="form-row">${field('Passed','passed','',{type:'number'})}${field('Failed','failed','',{type:'number'})}${field('Skipped','skipped','',{type:'number'})}${field('Total','total','',{type:'number'})}</div>${selectField('Host','host',[['','Unknown'],...state.hosts.map(h=>[h.id,h.label||h.id])])}${field('Run timestamp','started_at','',{placeholder:'ISO timestamp, if known'})}${field('Evidence reference','source','',{required:true,help:'Report path or another reference for this observation.'})}`,{form:'run',submit:'Record result'});}
function showRun(id){const r=historyData.runs.find(r=>r.id===id)||state.runs.find(r=>r.id===id)||state.repositories.flatMap(r=>r.runs||[]).find(r=>r.id===id);if(!r)return;openModal('Run evidence','These are the recorded facts for this observation.',`<dl class="definition">${[['Repository',r.repo_name||state.repositories.find(p=>p.id===r.repo_id)?.name||'Unmatched'],['Glade version',r.glade_version||'Unknown'],['Glade commit',r.glade_sha||'Unknown'],['Source commit',r.repo_sha||'Unknown'],['API version',r.api_version||'Unknown'],['Outcome',runLabel(r.status)],['Observed outcome',r.result_status?runLabel(r.result_status):'Not separately recorded'],['Phase',r.phase||'Not recorded'],['Part',r.part||'Not recorded'],['Shard',r.shard||'Not recorded'],['Passed',num(r.passed)],['Failed',num(r.failed)],['Skipped',num(r.skipped)],['Total',num(r.total)],['Compile errors',num(r.compile_errors)],['Runtime errors',num(r.runtime_errors)],['Unsupported',num(r.unsupported)],['Timeouts',num(r.timeouts)],['Run time',r.started_at||'Not recorded'],['Host',hostName(r.host)],['Identity match',r.identity_match||'Explicitly recorded'],['Provenance',r.provenance||'Not recorded'],['Evidence',r.source||'Not recorded']].map(([k,v])=>`<dt>${esc(k)}</dt><dd>${esc(typeof v==='object'?JSON.stringify(v):v)}</dd>`).join('')}</dl>`);}
function activityBody(){return `<div class="job-list">${state.jobs.length?[...state.jobs].reverse().map(j=>`<div class="job"><div class="job-top"><strong>${esc(j.kind||'Job')}</strong>${badge(j.status)}</div><p>${esc(j.message||'No detail recorded.')}</p><span class="secondary">${esc(time(j.started_at))}${j.finished_at?` → ${esc(time(j.finished_at))}`:''}</span></div>`).join(''):'<p class="small-note">No activity yet.</p>'}</div>`;}
function activity(){openModal('Workspace activity','Checks, imports, inventory refreshes, and prepared revisions.',activityBody());$('#modal').dataset.view='activity';}

function resetGroupScroll(){document.querySelectorAll('.group-cards').forEach(cards=>cards.scrollTop=0);const board=$('.group-board');if(board)board.scrollLeft=0;}

document.addEventListener('input',event=>{const settingsForm=event.target.closest('[data-form="settings"]');if(settingsForm)settingsForm.dataset.dirty='true';const filter=event.target.dataset.filter;if(filter&&event.target.tagName==='INPUT'){view[filter]=event.target.value;if(['groupSearch','groupUpstream','groupResult'].includes(filter))resetGroupScroll();view.repoPage=0;view.historyPage=0;view.candidatePage=0;render();if(view.tab==='history')scheduleHistory();}});
document.addEventListener('change',async event=>{const settingsForm=event.target.closest('[data-form="settings"]');if(settingsForm)settingsForm.dataset.dirty='true';if(event.target.dataset.selectRepo){if(event.target.checked)selectedRepos.add(event.target.dataset.selectRepo);else selectedRepos.delete(event.target.dataset.selectRepo);render();return;}if(event.target.dataset.tierRepo){await moveGroup(event.target.dataset.tierRepo,event.target.value);return;}const filter=event.target.dataset.filter;if(filter){view[filter]=event.target.value;if(['groupSearch','groupUpstream','groupResult'].includes(filter))resetGroupScroll();view.repoPage=0;view.historyPage=0;view.candidatePage=0;render();if(view.tab==='history')scheduleHistory();}});
document.addEventListener('click',async event=>{
  const button=event.target.closest('[data-action]');if(!button)return;const {action,id}=button.dataset;
  try {
    switch(action){
      case 'all-history':view.historySearch='';view.historyRepo='';view.historyStatus='';view.historyPhase='test';view.historyPage=0;location.hash='history';if(view.tab==='history')await loadHistory();break;
      case 'gate-history':view.historySearch=button.dataset.value;view.historyRepo='';view.historyStatus='';view.historyPhase='test';view.historyPage=0;location.hash='history';if(view.tab==='history')await loadHistory();break;
      case 'select-filtered':for(const repoId of view.filteredRepoIds||[])selectedRepos.add(repoId);render();break;
      case 'clear-selection':selectedRepos.clear();render();break;
      case 'test-selected':if(!selectedRepos.size){notify('Select repositories first.',true);break;}await mutate('/api/test-many',{repo_ids:[...selectedRepos]});selectedRepos.clear();render();break;
      case 'pull-selected':{const hosts=state.hosts.filter(h=>h.managed_root);if(!selectedRepos.size||!hosts.length){notify('Select repositories and configure a managed host.',true);break;}openModal('Pull selected updates','Each update creates a separate checkout. Pins and tracked checkouts remain unchanged.',selectField('Destination host','host',hosts.map(h=>[h.id,h.label||h.id]),state.settings.default_host||''),{form:'pull-selected',submit:'Pull updates'});break;}
      case 'attention':view.search='';view.host='';view.repoStatus='active';view.upstream=button.dataset.value;view.repoPage=0;location.hash='repositories';if(view.tab==='repositories')render();break;
      case 'cancel-job':await mutate(`/api/jobs/${encodeURIComponent(id)}/cancel`,{});break;
      case 'dismiss-job':await mutate(`/api/jobs/${encodeURIComponent(id)}/dismiss`,{});break;
      case 'delete-pull':if(confirm('Delete this dashboard-created checkout?'))await mutate(`/api/repos/${encodeURIComponent(id)}/delete-pull`,{location_id:button.dataset.location});break;
      case 'test-update':await mutate(`/api/repos/${encodeURIComponent(id)}/test-update`,{location_id:button.dataset.location});break;
      case 'keep-pin':await mutate(`/api/repos/${encodeURIComponent(id)}/keep-pin`,{location_id:button.dataset.location},'Kept the current pin.');break;
      case 'accept-pin':if(confirm('Accept this checkout as the pin? Its golden must be rebuilt in a reviewed PR.'))await mutate(`/api/repos/${encodeURIComponent(id)}/accept-pin`,{location_id:button.dataset.location,revision:state.settings.tiers?.revision},'Pin accepted; golden required.');break;
      case 'page':view[button.dataset.kind+'Page']+=Number(button.dataset.offset);if(button.dataset.kind==='history')await loadHistory();else render();break;
      case 'history-reload':await loadHistory();break;
      case 'repo-history':view.historyRepo=id;view.historySearch='';view.historyStatus='';view.historyPage=0;$('#detail').close();location.hash='history';if(view.tab==='history')await loadHistory();break;
      case 'clear-history-repo':view.historyRepo='';view.historyPage=0;await loadHistory();break;
      case 'track-checkout':await mutate(`/api/repos/${encodeURIComponent(id)}`,{tracked_location_id:button.dataset.location},'Tracking this checkout. Run an upstream check to compare its revision.');break;
      case 'import-bootstrap':await mutate('/api/import-bootstrap',{});break;
      case 'reload':await load({initial:true});break;
      case 'close-modal':closeModal();break;
      case 'close-detail':$('#detail').close();view.detail=null;break;
      case 'repo-detail':openDetail(id);break;
      case 'edit-repo':repoForm(id);break;
      case 'add-repo':openModal('Add repository','Register a GitHub repository, then prepare a checkout on the host you choose.',field('GitHub repository URL','url','',{required:true,placeholder:'https://github.com/owner/repository'}),{form:'repo-add',submit:'Add repository'});break;
      case 'check-repo':await mutate(`/api/repos/${encodeURIComponent(id)}/check`,{});break;
      case 'check-all':await mutate('/api/check',{});break;
      case 'scan':await mutate('/api/scan',{});break;
      case 'scan-host':await mutate('/api/scan',{host:id});break;
      case 'archive-repo':{const r=state.repositories.find(r=>r.id===id);if(r?.status==='archived'){await mutate(`/api/repos/${encodeURIComponent(id)}`,{status:'active'},'Restored to the active collection.');}else openModal('Archive repository','Remove this repository from the active collection. Its checkout files and run history remain intact.',`<input type="hidden" name="id" value="${esc(id)}"><p>${esc(r?.name||'Repository')}</p>`,{form:'archive',submit:'Archive repository'});break;}
      case 'snapshot':{const hosts=state.hosts.filter(h=>h.managed_root);if(!hosts.length){notify('Configure a managed checkout directory in Settings first.',true);break;}openModal('Prepare updated checkout','Create a separate checkout of the upstream revision. The old checkout remains intact, and no tests run.',`<input type="hidden" name="id" value="${esc(id)}">${selectField('Destination host','host',hosts.map(h=>[h.id,h.label||h.id]),state.settings.default_host||'')}<p class="small-note">The host must have sufficient free space. The new revision and checkout location are recorded in the catalog.</p>`,{form:'snapshot',submit:'Prepare checkout'});break;}
      case 'add-query':queryForm();break;
      case 'edit-query':queryForm(id);break;
      case 'run-query':await mutate(`/api/queries/${encodeURIComponent(id)}/run`,{});break;
      case 'delete-query':await mutate(`/api/queries/${encodeURIComponent(id)}/delete`,{},'Search deleted.');closeModal();if(view.query===id)view.query='';render();break;
      case 'filter-query':view.query=id||'';view.candidatePage=0;render();break;
      case 'check-project':await mutate(`/api/candidates/${encodeURIComponent(id)}/project-check`,{});break;
      case 'dismiss-candidate':await mutate(`/api/candidates/${encodeURIComponent(id)}`,{status:'dismissed'},'Candidate dismissed.');break;
      case 'restore-candidate':await mutate(`/api/candidates/${encodeURIComponent(id)}`,{status:'new'},'Candidate restored for review.');break;
      case 'add-candidate':await mutate(`/api/candidates/${encodeURIComponent(id)}/add`,{},'Added to your corpus.');break;
      case 'add-host':hostForm();break;
      case 'edit-host':hostForm(id);break;
      case 'import':importForm();break;
      case 'record-run':if(!state.repositories.length)notify('Add a repository before recording a result.',true);else runForm();break;
      case 'run-detail':showRun(id);break;
      case 'activity':activity();break;
      case 'export':{const data=await api('/api/export');const blob=new Blob([JSON.stringify({...data,exported_at:new Date().toISOString()},null,2)],{type:'application/json'});const href=URL.createObjectURL(blob),a=document.createElement('a');a.href=href;a.download=`glade-corpus-${new Date().toISOString().slice(0,10)}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(href),1000);break;}
    }
  }catch(error){notify(error.message,true);}
});
document.addEventListener('submit',async event=>{
  const form=event.target.closest('[data-form]');if(!form)return;event.preventDefault();const data=Object.fromEntries(new FormData(form));const submit=form.querySelector('[type="submit"]');if(submit)submit.disabled=true;const isModal=!!form.closest('dialog');const errorBox=form.querySelector('.form-error');if(errorBox)errorBox.hidden=true;
  try{
    switch(form.dataset.form){
      case 'pull-selected':await mutate('/api/pull-many',{repo_ids:[...selectedRepos],host:data.host});selectedRepos.clear();render();break;
      case 'settings':await mutate('/api/settings',{tiers_file:data.tiers_file,glade_binary:data.glade_binary,glade_sha:data.glade_sha,runner_binary:data.runner_binary,default_host:data.default_host},'Settings saved.');break;
      case 'repo-add':await mutate('/api/repos',{url:data.url.trim()},'Repository added.');break;
      case 'repo-edit':await mutate(`/api/repos/${encodeURIComponent(data.id)}`,{notes:data.notes,tags:data.tags.split(',').map(s=>s.trim()).filter(Boolean),status:data.status});break;
      case 'archive':await mutate(`/api/repos/${encodeURIComponent(data.id)}`,{status:'archived'},'Archived. Files and history are preserved.');break;
      case 'snapshot':await mutate(`/api/repos/${encodeURIComponent(data.id)}/snapshot`,{host:data.host});break;
      case 'query':if(!data.id)delete data.id;await mutate('/api/queries',data,'Search saved.');break;
      case 'host':if(!data.id)delete data.id;data.roots=data.roots.split('\n').map(s=>s.trim()).filter(Boolean);await mutate('/api/hosts',data,'Host saved.');break;
      case 'import':for(const k of Object.keys(data))if(!data[k])delete data[k];await mutate('/api/import',data);break;
      case 'run':for(const key of ['passed','failed','skipped','total'])data[key]=data[key]===''?null:Number(data[key]);for(const key of ['glade_sha','glade_version','repo_sha','api_version','started_at','host'])if(!data[key])delete data[key];await mutate('/api/runs',data,'Observed result recorded.');break;
    }
    if(form.dataset.form==='settings'){const current=$('#main form[data-form="settings"]');if(current)delete current.dataset.dirty;}
    if(submit)submit.disabled=false;
    if(isModal)closeModal();
  }catch(error){const current=form.dataset.form==='settings'?$('#main form[data-form="settings"]'):form;const target=current?.querySelector('.form-error')||errorBox;if(target){target.textContent=error.message;target.hidden=false;}else notify(error.message,true);if(submit)submit.disabled=false;}
});
$('#detail').addEventListener('close',()=>view.detail=null);
function navigate(){const tab=location.hash.slice(1),next=['overview','repositories','discover','history','groups','settings'].includes(tab)?tab:'overview',changed=next!==view.tab;view.tab=next;render();if(changed)window.scrollTo(0,0);if(view.tab==='history')loadHistory();}
window.addEventListener('hashchange',navigate);
view.tab=['overview','repositories','discover','history','groups','settings'].includes(location.hash.slice(1))?location.hash.slice(1):'overview';
load({initial:true});

async function moveGroup(id,tier){if(tier==='unassigned'&&!confirm('Remove this repository from the tiers file?')){render();return;}try{await mutate(`/api/repos/${encodeURIComponent(id)}/tier`,{tier,revision:state.settings.tiers?.revision});}catch(e){notify(e.message,true);await load();}}
document.addEventListener('dragstart',e=>{const card=e.target.closest('[data-repo]');if(card&&state.settings.tiers?.path)e.dataTransfer.setData('text/plain',card.dataset.repo);});
document.addEventListener('dragover',e=>{if(e.target.closest('[data-drop-tier]'))e.preventDefault();});
document.addEventListener('drop',e=>{const column=e.target.closest('[data-drop-tier]');if(column&&state.settings.tiers?.path){e.preventDefault();const id=e.dataTransfer.getData('text/plain');if(state.repositories.some(repo=>repo.id===id))moveGroup(id,column.dataset.dropTier);}});
